#include "../Source/SpectralDSP.h"
#include <vector>
#include <fstream>
#include <memory>
#include <cstdio>
#include <cstring>
#include <string>
#include <limits>
namespace {
constexpr double pi=3.14159265358979323846;
struct Band{double b,a1,a2,x1=0,x2=0,y1=0,y2=0;Band(double fs,double f,double q){double w=2*pi*f/fs,a=sin(w)/(2*q);b=a/(1+a);a1=-2*cos(w)/(1+a);a2=(1-a)/(1+a);}double tick(double x){double y=b*(x-x2)-a1*y1-a2*y2;x2=x1;x1=x;y2=y1;y1=y;return y;}};
std::vector<float> load(const char*path){std::ifstream f(path,std::ios::binary);char h[12];f.read(h,12);if(!f||memcmp(h,"RIFF",4)||memcmp(h+8,"WAVE",4))throw std::string("invalid fixture");bool fmt=false;while(f){char id[4];uint32_t n=0;f.read(id,4);f.read(reinterpret_cast<char*>(&n),4);if(!f)break;if(!memcmp(id,"fmt ",4)){std::vector<unsigned char>b(n);f.read(reinterpret_cast<char*>(b.data()),n);if(n<16||b[0]!=3||b[2]!=1||b[14]!=32)throw std::string("fixture must mono float32");uint32_t rate;memcpy(&rate,b.data()+4,4);if(rate!=48000)throw std::string("fixture rate");fmt=true;}else if(!memcmp(id,"data",4)){if(!fmt||n%4)throw std::string("fixture format");std::vector<float>x(n/4);f.read(reinterpret_cast<char*>(x.data()),n);if(!f||x.size()<48000)throw std::string("fixture short");return x;}else f.seekg(n,std::ios::cur);if(n&1)f.seekg(1,std::ios::cur);}throw std::string("fixture missing");}
std::vector<float> resample(const std::vector<float>&x,double fs){if(fs==48000)return x;std::vector<float>y(size_t(std::round(x.size()*fs/48000)));for(size_t i=0;i<y.size();++i){double p=i*48000/fs,v=0,norm=0;int k=int(p);for(int j=k-24;j<=k+24;++j){double d=p-j;if(std::abs(d)>=24)continue;double w=(d==0?1:sin(pi*d)/(pi*d))*(.5+.5*cos(pi*d/24));norm+=w;if(j>=0&&j<int(x.size()))v+=x[j]*w;}y[i]=float(v/norm);}return y;}
std::vector<float> render(const std::vector<float>&x,double fs,bool live,int depth,int sensitivity){auto d=std::make_unique<gillfinish::SilkDSP>();gillfinish::SilkParameters p;p.depth=float(depth);p.sensitivity=float(sensitivity);p.attackMs=4;p.releaseMs=140;d->setParameters(p);d->prepare(fs,127,1);d->setLiveMode(live);int lat=d->latencySamples();if(live&&lat)throw std::string("LIVE delay");auto y=x;y.resize(x.size()+lat+size_t(fs*.5));for(size_t i=0;i<y.size();i+=127){float*a[]{y.data()+i};d->process(a,int(std::min(size_t(127),y.size()-i)),1);}std::vector<float>z(y.begin()+lat,y.begin()+lat+x.size());for(float v:z)if(!std::isfinite(v))throw std::string("nonfinite");return z;}
double energy(const std::vector<float>&x,double fs,double hz){Band b(fs,hz,8);double e=0;for(size_t i=0;i<x.size();++i){double v=b.tick(x[i]);if(i>=fs*.5&&i<fs*5.8)e+=v*v;}return e;}
std::vector<float> difference(const std::vector<float>&a,const std::vector<float>&b){auto d=a;for(size_t i=0;i<d.size();++i)d[i]-=b[i];return d;}

double narrow(const std::vector<float>& x, int bin){constexpr int n=2048;std::array<double,n>re{},im{};for(int i=0;i<n;++i){double w=sin(pi*i/n);re[i]=w*cos(2*pi*bin*i/n);im[i]=-w*sin(2*pi*bin*i/n);}double sum=0;for(size_t at=24000;at+n<std::min(size_t(260160),x.size());at+=512){double r=0,q=0;for(int i=0;i<n;++i){r+=x[at+i]*re[i];q+=x[at+i]*im[i];}sum+=r*r+q*q;}return sum;}
int checks=0,failures=0;void check(bool b,const char*name,double value){++checks;failures+=!b;std::printf("%s %s %.9f\n",b?"PASS":"FAIL",name,value);}
}
int main(int argc,char**argv){try{if(argc!=2){std::fprintf(stderr,"Pass licensed dry_48k.wav fixture path\n");return 2;}auto speech=load(argv[1]);for(double fs:{44100.,48000.,88200.,96000.}){auto clean=resample(speech,fs);for(bool live:{false,true})for(int depth:{85,100}){int sensitivity=depth==85?70:100;auto z=render(clean,fs,live,depth,sensitivity);std::printf("REALVOICE %.0f %s %d/%d\n",fs,live?"LIVE":"PRO",depth,sensitivity);if(fs==48000&&!live)for(int bin:{31,82}){const double before=narrow(clean,bin),after=narrow(z,bin);const bool valid=std::isfinite(before)&&std::isfinite(after)&&before>0&&after>0;double change=valid?10*log10(after/before):std::numeric_limits<double>::quiet_NaN();std::printf("NARROW_BIN %d\n",bin);check(valid&&std::isfinite(change)&&std::abs(change)<(depth==85?3:6),"clean narrow peak preserved",change);}double body=10*log10(energy(z,fs,500)/energy(clean,fs,500)),upper=10*log10(energy(z,fs,5000)/energy(clean,fs,5000));check(std::abs(body)<1.5,"clean speech body within 1.5 dB",body);check(std::abs(upper)<1,"clean speech upper band within 1 dB",upper);for(double hz:{1040.,1480.,2900.,4100.}){Band room(fs,hz,24);auto dirty=clean;for(size_t i=0;i<dirty.size();++i)dirty[i]+=float(12*room.tick(clean[i]));auto y=render(dirty,fs,live,depth,sensitivity);double suppression=-10*log10(energy(difference(y,z),fs,hz)/energy(difference(dirty,clean),fs,hz));std::printf("ROOM_HZ %.1f\n",hz);check(suppression>(depth==85?1:3),"paired speech-driven resonance suppressed",suppression);}}}std::printf("SILK_REALVOICE_RESULT %d checks %d failures\n",checks,failures);return failures?1:0;}catch(const std::string&e){std::fprintf(stderr,"%s\n",e.c_str());return 2;}}
